from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def _parse(s: str, nesting_level: int = 0):
        if not s:
            return []

        opening_paren_index = s.find('(')
        closing_paren_index = s.find(')')

        if opening_paren_index == -1 and closing_paren_index == -1:
            return [nesting_level]

        if opening_paren_index == -1:
            return _parse(s[closing_paren_index+1:], nesting_level)

        if closing_paren_index == -1:
            return _parse(s[opening_paren_index+1:], nesting_level+1)

        return _parse(s[opening_paren_index+1: opening_paren_index+2], nesting_level+1) + _parse(s[closing_paren_index+1:], nesting_level)

    return _parse(paren_string)
```

