from string import ascii_lowercase, ascii_uppercase

def encrypt(s):
    encrypted = ""
    alphabet_lower = list(ascii_lowercase)
    alphabet_upper = list(ascii_uppercase)

    for char in s:
        if char.isalpha():
            if char.islower():
                rotated_index = (alphabet_lower.index(char) + 26 * 2) % 26
                encrypted += alphabet_lower[rotated_index]
            else:
                rotated_index = (alphabet_upper.index(char) + 26 * 2) % 26
                encrypted += alphabet_upper[rotated_index]
        else:
            encrypted += char

    return encrypted
```

