vowels = ['a', 'e', 'i', 'o', 'u']
shifted_vowels = ['c', 'o', 'l', 't', 'x']

def encode(message):
    """
    Encodes the given message by swapping case and replacing vowels with the letter that appears 2 places ahead of that vowel in the English alphabet.
    """
    encoded_message = ""
    for char in message:
        if char.isalpha():
            if char in vowels:
                encoded_message += shifted_vowels[vowels.index(char)]
            elif char.lower() in vowels:
                encoded_message += shifted_vowels[vowels.index(char.upper())]
            elif char.upper() in vowels:
