def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    visited = [[False for _ in range(N)] for _ in range(N)]
    paths = []

    def dfs(i, j, path, length):
        if length == k:
            paths.append(path)
            return

        for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            x, y = i + dx, j + dy
            if 0 <= x < N and 0 <= y < N and not visited[x][y]:
                visited[x][y] = True
                dfs(x, y, path + [grid[x][y]], length + 1)
                visited[x][y] = False

    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]], 1)

    # Find the lexicographically smallest path
    min_path = min(paths, key=lambda path: ''.join(str(x) for x in path))
    return list(map(int, min_path))
